<?php
use App\DB;use App\Otp;use App\Settings;
$row=DB::one('SELECT s.*,q.status quote_status,q.quote_number,q.issue_date,q.valid_until,q.company_snapshot,q.customer_snapshot,q.subtotal,q.discount_amount,q.tax_amount,q.total,q.prepayment,q.payable,q.notes,q.terms FROM quote_shares s JOIN quotes q ON q.id=s.quote_id WHERE s.token_hash=? AND s.revoked_at IS NULL AND s.expires_at>NOW()',[''.hash('sha256',$shareToken)]);
$error='';$allowed=false;$key='share_ok_'.$shareToken;$attemptKey='share_attempts_'.$shareToken;$otpKey='approve_mobile_'.$shareToken;$approveError='';$approveNotice='';
if($row){if(!empty($_SESSION[$key]))$allowed=true;elseif($_SERVER['REQUEST_METHOD']==='POST'&&!isset($_POST['stage'])){if((int)($_SESSION[$attemptKey]??0)>=8)$error='تعداد تلاش بیش از حد مجاز است؛ مرورگر را بسته و کمی بعد دوباره تلاش کنید.';elseif(password_verify((string)($_POST['password']??''),$row['password_hash'])){$_SESSION[$key]=true;unset($_SESSION[$attemptKey]);$allowed=true;DB::exec('UPDATE quote_shares SET view_count=view_count+1,last_viewed_at=NOW() WHERE id=?',[$row['id']]);}else{$_SESSION[$attemptKey]=(int)($_SESSION[$attemptKey]??0)+1;$error='رمز مشاهده نادرست است.';}}}
if(!$row){http_response_code(404);$error='این لینک معتبر نیست، منقضی شده یا توسط صادرکننده لغو شده است.';}
$company=$row?json_decode($row['company_snapshot'],true):[];$customer=$row?json_decode($row['customer_snapshot'],true):[];$items=$allowed?DB::all('SELECT * FROM quote_items WHERE quote_id=? ORDER BY sort_order,id',[$row['quote_id']]):[];
$approval=$allowed?DB::one('SELECT * FROM quote_approvals WHERE quote_id=? ORDER BY id DESC LIMIT 1',[$row['quote_id']]):null;
$canApprove=$allowed&&!$approval&&$row['quote_status']==='issued';
if($allowed&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['stage'])){
 if($_POST['stage']==='send_otp'&&$canApprove){
  $mobile=Otp::normalize((string)($_POST['mobile']??''));
  if(!$mobile)$approveError='شماره موبایل معتبر نیست.';
  else{[$ok,$msg]=Otp::send($mobile);if($ok){$_SESSION[$otpKey]=$mobile;$approveNotice='کد تأیید برای شماره '.$mobile.' ارسال شد.';}else $approveError=$msg;}
 }
 if($_POST['stage']==='verify_otp'&&$canApprove){
  $mobile=(string)($_SESSION[$otpKey]??'');$code=preg_replace('/\D+/','',(string)($_POST['code']??''));
  if(!$mobile)$approveError='ابتدا کد تأیید را درخواست کنید.';
  elseif(empty($_POST['consent']))$approveError='برای تایید، لازم است متن تعهدنامه را بپذیرید.';
  else{
   [$ok,$msg]=Otp::verifyOnly($mobile,$code);
   if(!$ok)$approveError=$msg;
   else{
    $template=(string)Settings::get('quote.approval_text','اینجانب پیش‌فاکتور شماره {quote_number} به مبلغ {payable} ریال ({payable_words} ریال) را تایید می‌نمایم.');
    $consentText=strtr($template,['{quote_number}'=>$row['quote_number'],'{payable}'=>number_format((float)$row['payable']),'{payable_words}'=>amount_to_words_fa((float)$row['payable'])]);
    DB::exec('INSERT INTO quote_approvals(quote_id,mobile,otp_verified_at,ip,user_agent,consent_text,amount_payable,quote_number)VALUES(?,?,NOW(),?,?,?,?,?)',[$row['quote_id'],$mobile,substr((string)($_SERVER['REMOTE_ADDR']??''),0,45),substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500),$consentText,$row['payable'],$row['quote_number']]);
    DB::exec("UPDATE quotes SET status='accepted' WHERE id=? AND status='issued'",[$row['quote_id']]);
    unset($_SESSION[$otpKey]);
    $approval=DB::one('SELECT * FROM quote_approvals WHERE quote_id=? ORDER BY id DESC LIMIT 1',[$row['quote_id']]);
    $canApprove=false;
   }
  }
 }
}
$otpSentTo=$_SESSION[$otpKey]??'';
$approvalTextPreview=$canApprove?strtr((string)Settings::get('quote.approval_text',''),['{quote_number}'=>$row['quote_number'],'{payable}'=>number_format((float)$row['payable']),'{payable_words}'=>amount_to_words_fa((float)$row['payable'])]):'';
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مشاهده پیش‌فاکتور</title><style>*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#111;font-family:Tahoma,sans-serif}.wrap{width:min(1100px,calc(100% - 24px));margin:24px auto}.card,.sheet{background:#fff;border:1px solid #ccd3dc;border-radius:12px;padding:24px}.card{max-width:420px;margin:10vh auto;text-align:center}input,button,textarea{font:inherit;padding:11px;border-radius:8px;border:1px solid #bbb;width:100%;margin-top:12px}button{background:#2563eb;color:#fff;border:0;cursor:pointer}.head{display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;border-bottom:2px solid #111;padding-bottom:12px}.head h1{text-align:center;font-size:20px}.meta{line-height:2}.party{border:1px solid #111;border-radius:7px;margin-top:12px;padding:12px;line-height:2}.party h2{font-size:14px;margin:0}.items{width:100%;border-collapse:collapse;margin-top:12px}.items th,.items td{border:1px solid #111;padding:7px;font-size:12px;text-align:center}.sign{display:grid;grid-template-columns:1fr 1fr;min-height:110px;border:1px solid #111;margin-top:12px;text-align:center;padding:15px}.tools{text-align:center;margin:12px}.tools button{width:auto;display:inline-block;padding:11px 22px}.approve-box{border:2px solid #2563eb;border-radius:10px;margin-top:16px;padding:16px;background:#f5f8ff}.approve-box h2{margin:0 0 8px;font-size:15px}.approve-box .consent-text{font-size:12px;line-height:2;background:#fff;border:1px solid #ccd3dc;border-radius:8px;padding:10px;max-height:160px;overflow-y:auto}.approve-box label.check{display:flex;align-items:center;gap:8px;font-size:12px;margin-top:10px}.approve-box label.check input{width:auto;margin-top:0}.notice{color:#0a7a30;font-size:12px}.err{color:#b91c1c;font-size:12px}.approved-badge{border:2px solid #0a7a30;background:#eafcef;border-radius:10px;padding:14px;text-align:center;margin-top:16px;color:#0a7a30;font-size:13px;line-height:2}@media print{body{background:#fff}.tools,.approve-box,.approved-badge{display:none}.wrap{width:100%;margin:0}.sheet{border:0;border-radius:0}}</style></head><body><?php if(!$allowed):?><form class="card" method="post"><h2>مشاهده امن پیش‌فاکتور</h2><p><?=e($error?:'رمز شش‌رقمی ارسال‌شده را وارد کنید.')?></p><?php if($row):?><input name="password" inputmode="numeric" maxlength="6" required autofocus placeholder="رمز مشاهده"><button>نمایش پیش‌فاکتور</button><?php endif;?></form><?php else:?><div class="tools"><button onclick="print()">چاپ / ذخیره PDF</button></div><main class="wrap sheet"><header class="head"><div><b><?=e($company['legal_name']??$company['name']??'')?></b></div><h1>پیش‌فاکتور فروش کالا و خدمات</h1><div class="meta">شماره: <?=e($row['quote_number'])?><br>تاریخ: <?=e($row['issue_date'])?></div></header><section class="party"><h2>فروشنده</h2><?=e($company['address']??'')?> — تلفن: <?=e($company['phone']??$company['mobile']??'')?> — شناسه ملی: <?=e($company['national_id']??'')?></section><section class="party"><h2>خریدار</h2><?=e($customer['name']??'')?> — تلفن: <?=e($customer['phone']??$customer['mobile']??'')?> — شناسه ملی: <?=e($customer['national_id']??'')?><br><?=e($customer['address']??'')?></section><table class="items"><thead><tr><th>ردیف</th><th>شرح</th><th>واحد</th><th>تعداد</th><th>مبلغ واحد</th><th>جمع</th></tr></thead><tbody><?php foreach($items as $i=>$item):?><tr><td><?=$i+1?></td><td><?=e($item['name'])?></td><td><?=e($item['unit'])?></td><td><?=number_format((float)$item['quantity'])?></td><td><?=number_format((float)$item['unit_price'])?></td><td><?=number_format((float)$item['line_total'])?></td></tr><?php endforeach;?><tr><th colspan="5">مبلغ قابل پرداخت</th><th><?=number_format((float)$row['payable'])?> ریال</th></tr></tbody></table><section class="party"><b>توضیحات:</b> <?=e($row['notes']??'-')?><br><b>شرایط پرداخت:</b> <?=e($row['terms']??'-')?></section><div class="sign"><div>مهر و امضای فروشنده</div><div>مهر و امضای خریدار</div></div>
<?php if($approval):?><div class="approved-badge">✔ این پیش‌فاکتور توسط مشتری تایید شده است.<br>شماره تاییدکننده: <?=e($approval['mobile'])?> — زمان تایید: <?=e($approval['otp_verified_at'])?><br>این تاییدیه با احراز هویت OTP، به‌عنوان امضای دیجیتال معتبر ثبت شده و قابل استناد است.</div>
<?php elseif($canApprove):?><div class="approve-box"><h2>تایید و پذیرش پیش‌فاکتور</h2><div class="consent-text"><?=nl2br(e($approvalTextPreview))?></div>
<?php if($approveError):?><p class="err"><?=e($approveError)?></p><?php endif;?><?php if($approveNotice):?><p class="notice"><?=e($approveNotice)?></p><?php endif;?>
<?php if(!$otpSentTo):?><form method="post"><input type="hidden" name="stage" value="send_otp"><input name="mobile" inputmode="tel" required placeholder="شماره موبایل شما" value="<?=e($customer['mobile']??'')?>"><button>دریافت کد تایید و امضای دیجیتال</button></form>
<?php else:?><form method="post"><input type="hidden" name="stage" value="verify_otp"><input name="code" inputmode="numeric" maxlength="6" required autofocus placeholder="کد ۶ رقمی ارسال‌شده به <?=e($otpSentTo)?>"><label class="check"><input type="checkbox" name="consent" required value="1"> متن فوق را مطالعه کردم و آن را می‌پذیرم.</label><button>تایید نهایی و ثبت امضای دیجیتال</button></form><form method="post"><input type="hidden" name="stage" value="send_otp"><input type="hidden" name="mobile" value="<?=e($otpSentTo)?>"><button style="background:#666">ارسال مجدد کد</button></form><?php endif;?></div>
<?php endif;?>
</main><?php endif;?></body></html>
